template <typename E, typename Cmp = std::less<E>>
class set {
  using index_type = detail::indexing<E, Cmp>;
  struct Getter { constexpr const E& operator()(const set*, const E* p) const noexcept { return *p; } };
  struct Predicate { constexpr bool operator()(const set* h, const E* e) const noexcept { return h->a[*e]; } };
 public:
  using container_type = bitset<E, index_type>;
  using key_type = E; using value_type = E; using size_type = std::size_t; using difference_type = std::ptrdiff_t; using key_compare = Cmp; using value_compare = Cmp;
  using reference = value_type&; using const_reference = const value_type&; using pointer = value_type*; using const_pointer = const value_type*;
  using iterator = detail::FilteredIterator<const set*, const E*, Getter, Predicate>;
  using const_iterator = detail::FilteredIterator<const set*, const E*, Getter, Predicate>;
  using reverse_iterator = std::reverse_iterator<iterator>;
  using const_reverse_iterator = std::reverse_iterator<const_iterator>;
  constexpr set() noexcept = default;
  template <typename InputIt>
  constexpr set(InputIt first, InputIt last) { while (first != last) { insert(*first++); } }
  constexpr set(std::initializer_list<E> ilist) { for (auto e : ilist) { insert(e); } }
  template <typename V, std::enable_if_t<std::is_same_v<V, E> && magic_enum::detail::subtype_v<V> == magic_enum::detail::enum_subtype::flags, int> = 0>
  constexpr explicit set(V starter) { auto u = enum_underlying(starter); for (E v : enum_values<E>()) { if ((enum_underlying(v) & u) != 0) { insert(v); } } }
  constexpr set(const set&) noexcept = default; constexpr set(set&&) noexcept = default;
  constexpr set& operator=(const set&) noexcept = default; constexpr set& operator=(set&&) noexcept = default;
  constexpr set& operator=(std::initializer_list<E> ilist) { for (auto e : ilist) { insert(e); } }
  constexpr const_iterator begin() const noexcept { return const_iterator{this, index_type::begin(), index_type::end(), index_type::begin()}; }
  constexpr const_iterator end() const noexcept { return const_iterator{this, index_type::begin(), index_type::end(), index_type::end()}; }
  constexpr const_iterator cbegin() const noexcept { return begin(); }
  constexpr const_iterator cend() const noexcept { return end(); }
  constexpr const_reverse_iterator rbegin() const noexcept { return {end()}; }
  constexpr const_reverse_iterator rend() const noexcept { return {begin()}; }
